CREATE TABLE IF NOT EXISTS community_representatives (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, representative_reference text NOT NULL, role_title text NOT NULL, mandate_status text NOT NULL DEFAULT 'Pending', mandate_scope text, mandate_start timestamptz, mandate_end timestamptz, verification_status text NOT NULL DEFAULT 'Pending', conflict_disclosure text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_mandates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, mandate_type text NOT NULL, status text NOT NULL DEFAULT 'Proposed', decision_reference text, quorum_requirement integer, quorum_met boolean NOT NULL DEFAULT false, effective_from timestamptz, effective_until timestamptz, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_decision_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, decision_type text NOT NULL, outcome text NOT NULL, participation_count integer NOT NULL DEFAULT 0, quorum_met boolean NOT NULL DEFAULT false, dissent_summary text, evidence_reference text, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_review_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, review_type text NOT NULL, status text NOT NULL DEFAULT 'Open', reviewer_reference text, independence_declaration text, issue_summary text, recommendation text, outcome text, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE IF NOT EXISTS community_appeals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_case_id uuid NOT NULL REFERENCES community_review_cases(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, appeal_reason text NOT NULL, status text NOT NULL DEFAULT 'Filed', decision text, decision_reference text, filed_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_community_reps ON community_representatives(community_id,mandate_status,verification_status);
CREATE INDEX IF NOT EXISTS idx_community_mandates ON community_mandates(community_id,status);
CREATE INDEX IF NOT EXISTS idx_community_decisions ON community_decision_records(community_id,asset_id,recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_community_reviews ON community_review_cases(community_id,asset_id,status);
CREATE INDEX IF NOT EXISTS idx_community_appeals ON community_appeals(community_id,asset_id,status);